        [MenuItem("Kingdom Tycoon/P14/Generate Raid Assets")]
        public static void Run() { ValidateContent(); GenerateScreen(); IntegrateBootstrapScene(); P14GeneratedAssetVerifier.Verify(); Debug.Log("P14_SETUP_COMPLETED"); }
        public static void ValidateContent()
        {
            string manifest = Path.GetFullPath(Path.Combine(UnityEngine.Application.dataPath, "StreamingAssets", "Content", "1.0.0-content.12", "content_manifest.json"));
            if (!File.Exists(manifest)) throw new BuildFailedException("P14_CONTENT_MANIFEST_MISSING"); string text = File.ReadAllText(manifest);
            if (!text.Contains("\"contentVersion\":\"1.0.0-content.12\"", StringComparison.Ordinal) || !text.Contains("\"csvSchemaSetVersion\":10", StringComparison.Ordinal)) throw new BuildFailedException("P14_CONTENT_MANIFEST_INVALID");
            string directory = Path.GetDirectoryName(manifest) ?? throw new BuildFailedException("P14_CONTENT_PATH_INVALID"); foreach (string file in new[] { "raids.csv", "raid_difficulties.csv", "raid_parts.csv", "raid_unlock_rules.csv", "raid_role_requirements.csv", "raid_part_target_rules.csv", "raid_boss_phase_rules.csv" }) if (!File.Exists(Path.Combine(directory, file))) throw new BuildFailedException("P14_CONTENT_TABLE_MISSING: " + file);
        }

