            Image background = Panel("Background", root.transform, new Color32(7, 13, 16, 255)); Stretch(background.rectTransform); Image top = Panel("BronzeTop", background.transform, new Color32(53, 37, 24, 255)); Rect(top.rectTransform, new Vector2(0, .91f), Vector2.one);
