            Image arena = Panel("Arena", safe.transform, new Color32(24, 31, 33, 255)); Rect(arena.rectTransform, new Vector2(.22f, .055f), new Vector2(.70f, .85f)); TMP_Text title = Text("BossTitle", arena.transform, "늪의 히드라  <size=24><color=#9FCFC2>일반</color></size>", 35, TextAlignmentOptions.Left, new Vector2(.04f, .89f), new Vector2(.78f, .98f), new Color32(244, 210, 124, 255));
