            Image hpTrack = Panel("BossHpTrack", bossFrame.transform, new Color32(17, 22, 23, 255)); Rect(hpTrack.rectTransform, new Vector2(.08f, .06f), new Vector2(.92f, .13f)); Image hpFill = Panel("P14_BOSS_HP_FILL", hpTrack.transform, new Color32(98, 162, 76, 255)); Rect(hpFill.rectTransform, Vector2.zero, Vector2.one); Text("BossHpText", hpTrack.transform, "우두머리 체력  100%", 17, TextAlignmentOptions.Center, Vector2.zero, Vector2.one);
            var partButtons = new Button[4]; var partLabels = new TMP_Text[4]; string[] partNames = { "머리\n<size=15>독 숨결 약화</size>", "몸통\n<size=15>방어력 감소</size>", "심장\n<size=15>격노 유발</size>", "예비 표적" }; for (int i = 0; i < 4; i++) { partButtons[i] = Button($"P14_PART_{i + 1}", arena.transform, partNames[i], i == 0 ? new Color32(92, 130, 66, 255) : new Color32(43, 54, 53, 255), 19); Rect(partButtons[i].GetComponent<RectTransform>(), new Vector2(.04f + i * .235f, .38f), new Vector2(.255f + i * .235f, .47f)); partLabels[i] = partButtons[i].GetComponentInChildren<TMP_Text>(); }
            Image tactical = Panel("TacticalPanel", arena.transform, new Color32(18, 27, 29, 255)); Rect(tactical.rectTransform, new Vector2(.04f, .055f), new Vector2(.96f, .35f)); TMP_Text result = Text("P14_RESULT", tactical.transform, "<color=#9FCFC2><b>작전 대기</b></color>\n표적 부위와 원정대를 확인한 뒤 출정하세요.", 21, TextAlignmentOptions.TopLeft, new Vector2(.04f, .46f), new Vector2(.96f, .92f)); TMP_Text trace = Text("P14_TRACE", tactical.transform, "00.0초  원정대 편성 대기\n--.-초  보스 단계 추적 준비", 17, TextAlignmentOptions.TopLeft, new Vector2(.04f, .08f), new Vector2(.96f, .43f), new Color32(139, 169, 162, 255));

            Image partyPanel = Panel("PartyPanel", safe.transform, new Color32(27, 37, 39, 255)); Rect(partyPanel.rectTransform, new Vector2(.71f, .055f), new Vector2(.985f, .85f)); TMP_Text partyCount = Text("PartyCount", partyPanel.transform, "원정대 0 / 8", 27, TextAlignmentOptions.Left, new Vector2(.06f, .90f), new Vector2(.64f, .98f), new Color32(241, 207, 119, 255)); Text("RoleGuide", partyPanel.transform, "탱커 · 힐러 · 원거리", 16, TextAlignmentOptions.Right, new Vector2(.44f, .91f), new Vector2(.94f, .97f), new Color32(141, 181, 170, 255));
            var memberButtons = new Button[8]; var memberLabels = new TMP_Text[8]; for (int i = 0; i < 8; i++) { memberButtons[i] = Button($"P14_MEMBER_{i + 1}", partyPanel.transform, $"<b>원정대원 {i + 1}</b>  {(i % 3 == 0 ? "수호자" : i % 3 == 1 ? "성직자" : "궁수")}\n<size=16>정예 · 전투력 {410 + i * 23} · 물약 2</size>", new Color32(45, 58, 57, 255), 19); Rect(memberButtons[i].GetComponent<RectTransform>(), new Vector2(.05f, .80f - i * .086f), new Vector2(.95f, .882f - i * .086f)); memberLabels[i] = memberButtons[i].GetComponentInChildren<TMP_Text>(); }
            TMP_Text warning = Text("P14_WARNING", partyPanel.transform, "<color=#F1B36A>주의 · 탱커 없음 · 힐러 없음</color>", 17, TextAlignmentOptions.Center, new Vector2(.05f, .11f), new Vector2(.95f, .18f)); Button deploy = Button("P14_DEPLOY", partyPanel.transform, "최소 6명을 편성하세요", new Color32(151, 89, 45, 255), 22); Rect(deploy.GetComponent<RectTransform>(), new Vector2(.05f, .025f), new Vector2(.95f, .105f)); TMP_Text deployLabel = deploy.GetComponentInChildren<TMP_Text>();

