            PrefabUtility.SaveAsPrefabAsset(root, ScreenPath); Object.DestroyImmediate(root); P14GeneratedAssetMarker marker = AssetDatabase.LoadAssetAtPath<P14GeneratedAssetMarker>(MarkerPath); if (marker == null) { marker = ScriptableObject.CreateInstance<P14GeneratedAssetMarker>(); AssetDatabase.CreateAsset(marker, MarkerPath); } marker.fingerprint = Fingerprint; EditorUtility.SetDirty(marker); AssetDatabase.SaveAssets(); AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
