        private static void IntegrateBootstrapScene()
        {
            Scene scene = EditorSceneManager.OpenScene(BootstrapScenePath, OpenSceneMode.Single); CommonUiRoot common = Object.FindFirstObjectByType<CommonUiRoot>(FindObjectsInactive.Include) ?? throw new BuildFailedException("P14_COMMON_UI_ROOT_MISSING"); Transform screens = common.transform.Find("ScreenCanvas") ?? throw new BuildFailedException("P14_SCREEN_CANVAS_MISSING"); foreach (Transform old in screens.Cast<Transform>().Where(value => value.name == "P14_RAID_SCREEN").ToArray()) Object.DestroyImmediate(old.gameObject);
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(ScreenPath) ?? throw new BuildFailedException("P14_UI_PREFAB_MISSING"); GameObject root = (GameObject)PrefabUtility.InstantiatePrefab(prefab, screens); root.name = "P14_RAID_SCREEN"; PrepareRoot(root); RaidScreenPresenter presenter = root.GetComponent<RaidScreenPresenter>(); root.SetActive(false);
            Transform hud = common.transform.Find("HudCanvas/SafeArea") ?? throw new BuildFailedException("P14_HUD_SAFE_AREA_MISSING"); Transform existing = hud.Find("P14_RAID_NAV_BUTTON"); if (existing != null) Object.DestroyImmediate(existing.gameObject); Button button = Button("P14_RAID_NAV_BUTTON", hud, "레이드", new Color32(132, 62, 52, 255), 22); RectTransform br = button.GetComponent<RectTransform>(); br.anchorMin = br.anchorMax = new Vector2(.79f, 0); br.offsetMin = new Vector2(0, 110); br.offsetMax = new Vector2(182, 190); RaidEntryButton entry = button.gameObject.AddComponent<RaidEntryButton>(); entry.Configure(presenter, button); UnityEventTools.AddPersistentListener(button.onClick, entry.OpenRaids); EditorSceneManager.MarkSceneDirty(scene); EditorSceneManager.SaveScene(scene);
        }
        internal static void PrepareRoot(GameObject root) { RectTransform rect = root.GetComponent<RectTransform>(); rect.localScale = Vector3.one; rect.anchorMin = rect.anchorMax = rect.pivot = new Vector2(.5f, .5f); rect.anchoredPosition = Vector2.zero; rect.sizeDelta = new Vector2(1920, 1080); CanvasGroup group = root.GetComponent<CanvasGroup>(); if (group != null) group.alpha = 1; }
        internal static void Capture(GameObject root, string directory, string filename, int width, int height)
        {
            root.SetActive(true); PrepareRoot(root); RectTransform rootRect = root.GetComponent<RectTransform>(); rootRect.sizeDelta = new Vector2(width, height); rootRect.position = Vector3.zero; Canvas canvas = root.GetComponent<Canvas>(); canvas.enabled = true;
            var cameraObject = new GameObject("P14CaptureCamera", typeof(Camera)); Camera camera = cameraObject.GetComponent<Camera>(); camera.clearFlags = CameraClearFlags.SolidColor; camera.backgroundColor = new Color32(7, 13, 16, 255); camera.orthographic = true; camera.orthographicSize = height / 2f; camera.nearClipPlane = .1f; camera.farClipPlane = 100f; camera.aspect = width / (float)height; camera.transform.position = new Vector3(0, 0, -10); camera.transform.rotation = Quaternion.identity;
            var target = new RenderTexture(width, height, 24, RenderTextureFormat.ARGB32); target.Create(); camera.targetTexture = target; canvas.renderMode = RenderMode.WorldSpace; canvas.worldCamera = camera; Canvas.ForceUpdateCanvases(); RenderTexture previous = RenderTexture.active; RenderTexture.active = target; GL.Clear(true, true, camera.backgroundColor); camera.Render(); var texture = new Texture2D(width, height, TextureFormat.RGB24, false); texture.ReadPixels(new Rect(0, 0, width, height), 0, 0); texture.Apply(false, false); string path = Path.Combine(directory, filename); File.WriteAllBytes(path, texture.EncodeToPNG()); RenderTexture.active = previous; camera.targetTexture = null; target.Release(); Object.DestroyImmediate(target); Object.DestroyImmediate(texture); Object.DestroyImmediate(cameraObject); canvas.renderMode = RenderMode.ScreenSpaceOverlay; canvas.worldCamera = null; if (new FileInfo(path).Length <= 100000) throw new BuildFailedException("P14_CAPTURE_FAILED: " + filename);
        }
        private static Image Panel(string name, Transform parent, Color color) { var go = new GameObject(name, typeof(RectTransform), typeof(Image)); go.transform.SetParent(parent, false); Image image = go.GetComponent<Image>(); image.color = color; return image; }
        private static TMP_Text Text(string name, Transform parent, string value, float size, TextAlignmentOptions alignment, Vector2 min, Vector2 max, Color? color = null) { var go = new GameObject(name, typeof(RectTransform), typeof(TextMeshProUGUI)); go.transform.SetParent(parent, false); TMP_Text text = go.GetComponent<TMP_Text>(); text.text = value; text.fontSize = size; text.alignment = alignment; text.color = color ?? new Color32(238, 231, 214, 255); text.textWrappingMode = TextWrappingModes.Normal; text.overflowMode = TextOverflowModes.Overflow; text.raycastTarget = false; Rect(text.rectTransform, min, max); return text; }
        private static Button Button(string name, Transform parent, string label, Color color, float size) { Image image = Panel(name, parent, color); Button button = image.gameObject.AddComponent<Button>(); button.targetGraphic = image; ColorBlock colors = button.colors; colors.highlightedColor = Color.Lerp(color, Color.white, .12f); colors.pressedColor = Color.Lerp(color, Color.black, .16f); colors.disabledColor = new Color(color.r * .55f, color.g * .55f, color.b * .55f, .72f); button.colors = colors; Text("Label", image.transform, label, size, TextAlignmentOptions.Center, Vector2.zero, Vector2.one); return button; }
        private static void Stretch(RectTransform value) => Rect(value, Vector2.zero, Vector2.one); private static void Rect(RectTransform value, Vector2 min, Vector2 max) { value.anchorMin = min; value.anchorMax = max; value.offsetMin = value.offsetMax = Vector2.zero; }
        private static void EnsureFolder(string path) { string current = "Assets"; foreach (string segment in path.Split('/').Skip(1)) { string next = current + "/" + segment; if (!AssetDatabase.IsValidFolder(next)) AssetDatabase.CreateFolder(current, segment); current = next; } }
    }

    public static class P14GeneratedAssetVerifier
    {
        [MenuItem("Kingdom Tycoon/P14/Verify Generated Assets")]
        public static void Verify()
        {
            P14RaidSetup.ValidateContent(); P14GeneratedAssetMarker marker = AssetDatabase.LoadAssetAtPath<P14GeneratedAssetMarker>(P14RaidSetup.MarkerPath); if (marker == null || marker.fingerprint != P14RaidSetup.Fingerprint) throw new BuildFailedException("P14_GENERATED_FINGERPRINT_INVALID"); GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(P14RaidSetup.ScreenPath) ?? throw new BuildFailedException("P14_UI_PREFAB_MISSING"); Transform[] nodes = prefab.GetComponentsInChildren<Transform>(true); foreach (string id in P14RaidSetup.RequiredIds) if (nodes.Count(value => value.name == id) != 1) throw new BuildFailedException("P14_UI_ID_INVALID: " + id); prefab.SetActive(true); P14RaidSetup.PrepareRoot(prefab); Canvas.ForceUpdateCanvases(); string[] invalid = prefab.GetComponentsInChildren<Button>(true).Where(value => value.GetComponent<RectTransform>().rect.width < 64 || value.GetComponent<RectTransform>().rect.height < 64).Select(value => value.name).ToArray(); prefab.SetActive(false); if (invalid.Length > 0) throw new BuildFailedException("P14_TOUCH_TARGET_INVALID: " + string.Join(",", invalid)); Scene scene = EditorSceneManager.OpenScene(P14RaidSetup.BootstrapScenePath, OpenSceneMode.Single); RaidScreenPresenter[] screens = scene.GetRootGameObjects().SelectMany(value => value.GetComponentsInChildren<RaidScreenPresenter>(true)).ToArray(); RaidEntryButton[] entries = scene.GetRootGameObjects().SelectMany(value => value.GetComponentsInChildren<RaidEntryButton>(true)).ToArray(); if (screens.Length != 1 || entries.Length != 1) throw new BuildFailedException($"P14_SCENE_ENTRY_INVALID: screens={screens.Length}, entries={entries.Length}"); Button button = entries[0].GetComponent<Button>(); if (button == null || button.onClick.GetPersistentEventCount() != 1 || button.onClick.GetPersistentTarget(0) != entries[0]) throw new BuildFailedException("P14_SCENE_ENTRY_BINDING_INVALID"); Debug.Log("P14_ASSETS_VERIFIED");
        }
    }

    public static class P14CaptureGenerator
    {
        [MenuItem("Kingdom Tycoon/P14/Generate Acceptance Captures")]
