        {
            P14GeneratedAssetVerifier.Verify(); Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single); GameObject root = (GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(P14RaidSetup.ScreenPath), scene); root.SetActive(true); P14RaidSetup.PrepareRoot(root); Transform[] nodes = root.GetComponentsInChildren<Transform>(true); string output = Path.GetFullPath(Path.Combine(UnityEngine.Application.dataPath, "..", "..", "docs", "reports", "captures", "P14")); Directory.CreateDirectory(output); P14RaidSetup.Capture(root, output, "p14_01_hydra_prep.png", 1920, 1080);
            nodes.Single(value => value.name == "P14_BOSS_HP_FILL").GetComponent<RectTransform>().anchorMax = new Vector2(.63f, 1); nodes.Single(value => value.name == "P14_RESULT").GetComponent<TMP_Text>().text = "<color=#F4D27A><b>전투 진행 중</b></color>  02:14\n히드라 몸통 파괴 · 방어력 감소 활성"; nodes.Single(value => value.name == "P14_TRACE").GetComponent<TMP_Text>().text = "12.0초  맹독 이빨  생명력 58,400\n48.0초  몸통 파괴  생명력 41,200\n74.0초  독성 숨결  생명력 32,500"; P14RaidSetup.Capture(root, output, "p14_02_hydra_combat.png", 1920, 1080);
            nodes.Single(value => value.name == "P14_BOSS_HP_FILL").GetComponent<RectTransform>().anchorMax = new Vector2(0, 1); nodes.Single(value => value.name == "P14_RESULT").GetComponent<TMP_Text>().text = "<color=#F4D27A><b>토벌 성공</b></color>  184.3초\n파괴 부위: 머리, 몸통 · 보상: 히드라 심장 x1"; P14RaidSetup.Capture(root, output, "p14_03_hydra_result.png", 1920, 1080);
            nodes.Single(value => value.name == "P14_RAID_1").GetComponent<Image>().color = new Color32(38, 49, 50, 255); nodes.Single(value => value.name == "P14_RAID_4").GetComponent<Image>().color = new Color32(137, 60, 55, 255); nodes.Single(value => value.name == "BossTitle").GetComponent<TMP_Text>().text = "재의 고룡  <size=24><color=#E8A49B>일반</color></size>"; nodes.Single(value => value.name == "Briefing").GetComponent<TMP_Text>().text = "제한 시간 6:00  ·  편성 6~8명  ·  최고 기록 212.6초"; nodes.Single(value => value.name == "BossFrame").GetComponent<Image>().color = new Color32(47, 31, 35, 255); nodes.Single(value => value.name == "BossAura").GetComponent<Image>().color = new Color32(126, 47, 45, 210); nodes.Single(value => value.name == "BossGlyph").GetComponent<TMP_Text>().text = "△\n<size=19>잿빛 하늘의 폭군</size>"; nodes.Single(value => value.name == "P14_BOSS_HP_FILL").GetComponent<Image>().color = new Color32(173, 67, 61, 255); nodes.Single(value => value.name == "P14_BOSS_HP_FILL").GetComponent<RectTransform>().anchorMax = new Vector2(0, 1); string[] dragonParts = { "뿔\n<size=15>돌진 약화</size>", "날개\n<size=15>비행 봉쇄</size>", "몸통\n<size=15>방어력 감소</size>", "심장\n<size=15>최종 격노</size>" }; for (int index = 0; index < 4; index++) nodes.Single(value => value.name == $"P14_PART_{index + 1}").GetComponentInChildren<TMP_Text>().text = dragonParts[index]; nodes.Single(value => value.name == "P14_RESULT").GetComponent<TMP_Text>().text = "<color=#F4D27A><b>1차 결말 해금</b></color>\n재의 고룡 토벌 완료 · 변형 레이드 개방"; nodes.Single(value => value.name == "P14_TRACE").GetComponent<TMP_Text>().text = "42.0초  뿔 파괴  생명력 142,300\n118.0초  비행 봉쇄  생명력 86,900\n212.6초  잿빛 고룡 토벌"; P14RaidSetup.Capture(root, output, "p14_04_dragon_ending.png", 1920, 1080); P14RaidSetup.Capture(root, output, "p14_05_20x9.png", 2400, 1080); Debug.Log($"P14_CAPTURES={output}; count=5");
        }
    }

    public static class P14AndroidBuilder
